package com.example.tracking.config;import io.swagger.v3.oas.models.OpenAPI;import io.swagger.v3.oas.models.info.Info;import org.springframework.context.annotation.*;import org.springframework.web.servlet.config.annotation.*;@Configuration public class AppConfig implements WebMvcConfigurer{@Bean OpenAPI api(){return new OpenAPI().info(new Info().title("Tracking Service API").version("1.0.0").description("Kafka-backed order lifecycle read model"));}@Override public void addCorsMappings(CorsRegistry registry){registry.addMapping("/api/**").allowedOrigins("http://localhost:5174").allowedMethods("GET");}}
